#include "theme.hpp"
#include <QApplication>
#include <QPalette>
#include <QRegularExpression>
#include <QMap>
#include <QPlainTextEdit>
#include <QTextDocument>
#include <QSyntaxHighlighter>
void Theme::apply(bool dark){
    qApp->setProperty("darkMode",dark);
    QPalette p;p.setColor(QPalette::Window,dark?QColor("#101722"):QColor("#f4f7fb"));p.setColor(QPalette::WindowText,dark?QColor("#e2e8f0"):QColor("#27364b"));p.setColor(QPalette::Base,dark?QColor("#17212f"):QColor("#ffffff"));p.setColor(QPalette::AlternateBase,dark?QColor("#111b29"):QColor("#f8fafc"));p.setColor(QPalette::Text,p.color(QPalette::WindowText));p.setColor(QPalette::Button,p.color(QPalette::Base));p.setColor(QPalette::ButtonText,p.color(QPalette::Text));p.setColor(QPalette::Highlight,QColor("#0d9488"));p.setColor(QPalette::HighlightedText,Qt::white);p.setColor(QPalette::Mid,dark?QColor("#475569"):QColor("#dbe4ef"));p.setColor(QPalette::PlaceholderText,dark?QColor("#aab7c9"):QColor("#64748b"));qApp->setPalette(p);
    QString style=R"QSS(QMainWindow {background:#f4f7fb;} QMenuBar {background:#ffffff;padding:3px;color:#334155;} QMenuBar::item {padding:5px 9px;} QToolBar#speedBar {background:white;padding:4px;border-bottom:1px solid #e2e8f0;} QToolBar#commandBar {background:white;spacing:5px;padding:9px;border-bottom:1px solid #e2e8f0;} QToolButton {padding:7px 9px;border-radius:6px;color:#334155;} QToolButton:hover {background:#edf4f5;} QToolButton:checked {background:#e0f4f1;color:#0d9488;} QToolButton#runButton {background:#0d9488;color:white;padding:9px 15px;font-weight:600;} QToolButton#runButton:hover {background:#0f766e;} QLabel#brandName {font-size:18px;font-weight:700;color:#173747;} QLabel#sectionTitle {font-weight:600;color:#334155;} QLabel#muted {color:#7b8ba0;font-size:11px;} QDockWidget {color:#64748b;font-weight:600;} QDockWidget::title {background:#f4f7fb;padding:8px;} QMainWindow::separator {width:5px;height:5px;background:#e8edf4;} QPushButton {background:white;border:1px solid #dce4ee;border-radius:7px;padding:8px 10px;color:#334155;} QPushButton:hover {background:#edf8f6;border-color:#b3d8d2;} QPushButton#componentCard {text-align:left;padding:10px 12px;font-weight:500;} QPlainTextEdit {background:white;border:0;color:#27364b;selection-background-color:#cdebe7;selection-color:#173747;} QTabWidget::pane {border:0;background:white;} QTabBar::tab {background:#f1f5f9;padding:9px 12px;color:#718096;border-bottom:2px solid transparent;} QTabBar::tab:selected {background:white;color:#0d9488;border-bottom:2px solid #0d9488;} QDoubleSpinBox,QComboBox {background:white;border:1px solid #dce4ee;border-radius:5px;padding:7px;} QStatusBar {background:#ffffff;border-top:1px solid #e2e8f0;color:#748398;} QStatusBar::item {border:0;} )QSS";
    if(dark){const QMap<QString,QString> colors{{"white","#17212f"},{"#ffffff","#17212f"},{"#f4f7fb","#101722"},{"#334155","#e2e8f0"},{"#27364b","#e2e8f0"},{"#173747","#d5f5ed"},{"#64748b","#aab7c9"},{"#718096","#b5c4d8"},{"#7b8ba0","#aab7c9"},{"#748398","#aab7c9"},{"#e2e8f0","#344154"},{"#dce4ee","#344154"},{"#e8edf4","#253247"},{"#f1f5f9","#101722"},{"#edf4f5","#253247"},{"#edf8f6","#253247"}};QString result;int offset=0;auto matches=QRegularExpression("#[A-Fa-f0-9]{6}|\\bwhite\\b").globalMatch(style);while(matches.hasNext()){const auto m=matches.next();result+=style.mid(offset,m.capturedStart()-offset)+colors.value(m.captured(),m.captured());offset=m.capturedEnd();}style=result+style.mid(offset);}
    style+="QMenu {background:#111111;color:#ffffff;border:1px solid #444;padding:5px;} QMenu::item {padding:7px 28px 7px 20px;color:#ffffff;background:#111111;} QMenu::item:selected {background:#303030;color:#ffffff;} QMenu::item:disabled {color:#9ca3af;} QMenu::separator {height:1px;background:#444;margin:4px;} QMenuBar::item:selected,QMenuBar::item:pressed {background:#111111;color:#ffffff;} QTabBar::tab:hover {background:#111111;color:#ffffff;} QToolTip {background:#111111;color:#ffffff;border:1px solid #555;} QToolButton#runButton {color:#ffffff;} QTreeView,QListView,QTextBrowser {background:"+p.color(QPalette::Base).name()+";color:"+p.color(QPalette::Text).name()+";}";
    const QString base=p.color(QPalette::Base).name(),text=p.color(QPalette::Text).name(),border=p.color(QPalette::Mid).name();
    style+="QToolButton#resetButton {background:"+base+";color:"+text+";border:1px solid "+border+";border-radius:6px;padding:8px 14px;font-weight:600;} QToolButton#resetButton:hover {background:"+(dark?QString("#253247"):QString("#edf4f5"))+";border-color:#4285d4;}";
    style+="QWidget#startPage {background:"+p.color(QPalette::Window).name()+";} QFrame#startSidebar {background:"+base+";border-right:1px solid "+border+";} QLabel#startBrand {font-size:24px;font-weight:700;color:"+text+";} QLabel#welcomeTitle {font-size:27px;font-weight:700;color:"+text+";} QLabel#welcomeSubtitle {font-size:14px;color:"+(dark?QString("#aab7c9"):QString("#64748b"))+";} QLabel#recentTitle {font-size:17px;font-weight:600;color:"+text+";} QFrame#welcomeHero {background:"+(dark?QString("#193546"):QString("#e4f2f4"))+";border:1px solid "+(dark?QString("#2a5363"):QString("#c5e1e4"))+";border-radius:12px;} QLabel#heroTitle {font-size:21px;font-weight:600;color:"+text+";} QLabel#heroSubtitle {color:"+text+";} QFrame#recentProjectCard {background:"+base+";border:1px solid "+border+";border-radius:9px;} QLabel#recentFileName {font-weight:600;color:"+text+";} QLabel#recentLocation {color:"+(dark?QString("#aab7c9"):QString("#64748b"))+";font-size:11px;} QPushButton#recentProject {text-align:left;border:0;background:transparent;font-weight:600;padding:8px;} QPushButton#recentProject:hover {background:"+(dark?QString("#253247"):QString("#edf4f5"))+";} QPushButton#homeNavigation,QPushButton#settingsNavigation,QPushButton#tutorialNavigation,QPushButton#resumeEditor {text-align:left;border:0;padding:10px 8px;} QPushButton#homeNavigation:checked,QPushButton#settingsNavigation:checked {background:"+(dark?QString("#193d40"):QString("#def1ed"))+";color:"+text+";} QPushButton#startNewProject {background:#0d9488;color:#ffffff;border:1px solid #0d9488;font-weight:600;padding:10px 14px;} QPushButton#startNewProject:hover {background:#0f766e;} QPushButton#startOpenProject {padding:10px 14px;} QPushButton#startExamples {text-align:left;padding:16px;} QPushButton#clearRecentProjects {font-size:11px;padding:5px 8px;} QPushButton#removeRecentProject {padding:0;border:0;font-size:19px;} QLabel#emptyProjects {padding:25px;color:"+(dark?QString("#aab7c9"):QString("#64748b"))+";}";
    qApp->setStyleSheet(style);for(auto* widget:qApp->allWidgets())if(auto* editor=qobject_cast<QPlainTextEdit*>(widget))for(auto* highlighter:editor->document()->findChildren<QSyntaxHighlighter*>())highlighter->rehighlight();
}
